"""English guides — crypto (translations of guides_3; French tax guide left out)."""


def _prev(i, nom, sym, extra, q=None):
    return {"i": i, "c": "crypto", "h": f"{nom} forecast: what to expect next month?",
            "t": f"{nom} ({sym}) forecast: today's AI analysis",
            "d": f"{nom} forecast: expected volatility, risk of a sharp drop and what AI can really predict about {sym}, updated daily.",
            "r": f"Nobody can reliably say whether {nom} will be higher or lower in a month: the radar's test shows it. Its **volatility** and **risk of a sharp drop**, however, can be forecast much better, and they are updated every day below.",
            "p": [(f"What to know about {nom}", extra),
                  ("What the AIs predict well", f"How much {nom} is likely to move next month, and the probability that it loses more than 10%. On years never seen, both forecasts clearly beat simple methods."),
                  ("What they cannot do", "Guess the direction of the price. On cryptos, the radar's AIs even did worse than the rule \"it always goes up\" in the test, so the site shows the usual trend rather than an unproven opinion.")],
            "q": q or [(f"Will {nom} go up?", "Nobody knows reliably. Be wary of anyone who claims certainty, especially if they have something to sell.")]}


